def parse_amount(text):
    """Turn text like '1,250.50' into a number, or raise a clear error."""
    cleaned = text.strip().replace(",", "")
    try:
        value = float(cleaned)
    except ValueError:
        raise ValueError(f"'{text}' is not a number") from None
    if value < 0:
        raise ValueError("Amount cannot be negative")
    return value

